/** The unread mark: a static 6 px dot. It never pulses; the dot itself is the news. */
export function UnreadDot({ className }: { className?: string }) {
  return (
    <span
      data-slot="unread-dot"
      className={cn("bg-(color:--chatcn-fg) block size-1.5 shrink-0 rounded-full", className)}
    />
  )
}

export interface RunProgressProps extends React.ComponentProps<"div"> {
  /** 0 to 1. Undefined means indeterminate. */
  value?: number
  /** Accessible name. Default "Progress". */
  label?: string
}

/**
 * 2 px progress line. Determinate fills with a scaleX transform (280 ms, so jumps between steps
 * read as progress, not teleports). Indeterminate slides a third-width segment with the Web
 * Animations API; under reduced motion the segment sits still.
 */
export function RunProgress({ value, label = "Progress", className, ...props }: RunProgressProps) {
  const segment = React.useRef<HTMLSpanElement>(null)
  const indeterminate = value === undefined

  React.useEffect(() => {
    const el = segment.current
    if (!indeterminate || !el || typeof el.animate !== "function") return
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return
    const rtl = getComputedStyle(el).direction === "rtl"
    const from = rtl ? "100%" : "-100%"
    const to = rtl ? "-300%" : "300%"
    const animation = el.animate(
      [{ transform: `translateX(${from})` }, { transform: `translateX(${to})` }],
      {
        duration: 1600,
        iterations: Number.POSITIVE_INFINITY,
        easing: "cubic-bezier(0.77, 0, 0.175, 1)",
      },
    )
    return () => animation.cancel()
  }, [indeterminate])

  return (
    <div
      role="progressbar"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={indeterminate ? undefined : Math.round(value * 100)}
      data-slot="run-progress"
      data-indeterminate={indeterminate ? "" : undefined}
      className={cn("bg-(color:--chatcn-alpha-200) relative h-0.5 overflow-hidden", className)}
      {...props}
    >
      {indeterminate ? (
        <span
          ref={segment}
          className="bg-(color:--chatcn-accent) absolute inset-y-0 start-1/3 w-1/3 rounded-full motion-reduce:opacity-40"
        />
      ) : (
        <span
          className={cn(
            "bg-(color:--chatcn-accent) absolute inset-0 origin-left rtl:origin-right",
            "ease-(--chatcn-ease-out) transition-transform duration-280 motion-reduce:transition-none",
          )}
          style={{ transform: `scaleX(${value})` }}
        />
      )}
    </div>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export type BackgroundRunStatus = "queued" | "running" | "needs-input" | "done" | "failed" | "cancelled"

export interface BackgroundRunData {
  id: string
  title: React.ReactNode
  status: BackgroundRunStatus
  /** Where it runs, set small under the title: repo and branch, a project, an environment. */
  context?: React.ReactNode
  /** The latest step, one line. Crossfades when it changes. */
  step?: React.ReactNode
  /** What the agent waits for in `needs-input`, for example "Approve pnpm db:migrate". */
  request?: React.ReactNode
  /** Outcome line for `done` and `cancelled`, for example "3 files changed, 12 tests pass". */
  summary?: React.ReactNode
  /** Why it failed, and how to fix it, for `failed`. */
  error?: React.ReactNode
  /** 0 to 1. Leave undefined for an indeterminate bar while running. */
  progress?: number
  /** Steps done and total. Sets `progress` and shows "3 of 7". */
  steps?: { done: number; total: number }
  /** Runs ahead of this one, for `queued`. */
  queuePosition?: number
  /** Epoch ms when the run started. */
  startedAt?: number
  /** Final run time in ms, for finished runs. */
  durationMs?: number
  /** New activity the user has not seen. Shows a static dot. Never pulses. */
  unread?: boolean
}

/* -------------------------------------------------------------------------------------------------
 * BackgroundRunRow (list)
 * -----------------------------------------------------------------------------------------------*/

export interface BackgroundRunRowProps extends Omit<React.ComponentProps<"button">, "title"> {
  run: BackgroundRunData
  selected?: boolean
}

const isActive = (status: BackgroundRunStatus) => status === "running" || status === "needs-input"

interface UseChatcnElapsedOptions {
  /** True while the timed work is happening. */
  running: boolean
  /** Epoch ms when the work started. Measured from the first `running` render when omitted. */
  startedAt?: number
  /** Final duration from the runtime. Wins over the measured one once `running` is false. */
  durationMs?: number
}

interface UseChatcnElapsedResult {
  /** Live elapsed ms while running, the final duration afterwards, `undefined` when unknown. */
  ms: number | undefined
  running: boolean
}

/**
 * Elapsed time for a step, a run or a reasoning block.
 *
 * Ticks once per second, aligned to the start time so the counter turns over exactly at 1 s,
 * 2 s and so on, never at random offsets. A counter that changes faster only adds noise.
 */
function useChatcnElapsed({
  running,
  startedAt,
  durationMs,
}: UseChatcnElapsedOptions): UseChatcnElapsedResult {
  const [autoStart, setAutoStart] = React.useState<number>()
  const [measured, setMeasured] = React.useState<number>()
  // Starts empty and reads the clock after mount: a render must not read it (Next.js prerender).
  const [now, setNow] = React.useState<number | null>(null)
  const start = startedAt ?? autoStart

  // Record our own start when the caller gives none. A new run (running again) starts over.
  React.useEffect(() => {
    if (!running) return
    if (startedAt === undefined) setAutoStart((prev) => prev ?? Date.now())
    setMeasured(undefined)
    setNow(Date.now())
  }, [running, startedAt])

  // Freeze the measured duration when the work stops.
  const wasRunning = React.useRef(running)
  React.useEffect(() => {
    if (wasRunning.current && !running && start !== undefined) {
      setMeasured(Date.now() - start)
      setAutoStart(undefined)
    }
    wasRunning.current = running
  }, [running, start])

  React.useEffect(() => {
    if (!running || start === undefined) return
    let id: number
    const schedule = () => {
      const elapsed = Date.now() - start
      // Next whole-second boundary, plus a few ms so rounding never shows the old second.
      const wait = 1000 - (((elapsed % 1000) + 1000) % 1000) + 8
      id = window.setTimeout(() => {
        setNow(Date.now())
        schedule()
      }, wait)
    }
    schedule()
    return () => window.clearTimeout(id)
  }, [running, start])

  if (running)
    return { ms: start === undefined ? undefined : Math.max(0, (now ?? start) - start), running }
  return { ms: durationMs ?? measured, running }
}

const NBSP = " "

/**
 * Formats a duration the chatcn way: numerals, a non-breaking space before the unit.
 * `precise` (the default) keeps a decimal under 10 s and milliseconds under 1 s, for finished
 * steps. Turn it off for live counters and "Thought for 12 s", which read in whole seconds.
 */
function formatChatcnDuration(ms: number, { precise = true }: { precise?: boolean } = {}) {
  const safe = Math.max(0, ms)
  if (precise && safe < 1000) return `${Math.max(1, Math.round(safe))}${NBSP}ms`
  const s = safe / 1000
  if (precise && s < 10) return `${s.toFixed(1)}${NBSP}s`
  if (s < 60) return `${precise ? Math.round(s) : Math.floor(s)}${NBSP}s`
  const totalS = Math.floor(s)
  const h = Math.floor(totalS / 3600)
  const m = Math.floor((totalS % 3600) / 60)
  const rest = totalS % 60
  if (h > 0) return `${h}${NBSP}h ${m}${NBSP}m`
  return `${m}${NBSP}m ${rest}${NBSP}s`
}

function useRunTime(run: Pick<BackgroundRunData, "status" | "startedAt" | "durationMs">) {
  const active = isActive(run.status)
  const { ms } = useChatcnElapsed({
    running: active,
    startedAt: run.startedAt,
    durationMs: run.durationMs,
  })
  if (run.status === "queued" || ms === undefined) return undefined
  if (active && ms < 1000) return undefined
  // Whole seconds while it ticks, a decimal once it is done (matches ToolCall).
  return formatChatcnDuration(ms, { precise: !active })
}

function secondaryLine(run: BackgroundRunData) {
  switch (run.status) {
    case "queued":
      return run.queuePosition
        ? `Starts after ${run.queuePosition} ${run.queuePosition === 1 ? "run" : "runs"}`
        : (run.step ?? "Waiting for a machine")
    case "needs-input":
      return run.request ?? run.step ?? "Waiting for you"
    case "done":
    case "cancelled":
      return run.summary ?? run.step
    case "failed":
      return run.error ?? run.step
    default:
      return run.step
  }
}

/** The kit's one spinner. 0.8 s per turn, slowed to 1.2 s under reduced motion. */
function Spinner({ className, label }: { className?: string; label?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      data-slot="spinner"
      className={cn("chatcn-spin size-3.5 shrink-0", className)}
    >
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeOpacity="0.2" strokeWidth="1.5" />
      <path
        d="M8 1.75A6.25 6.25 0 0 1 14.25 8"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
      />
    </svg>
  )
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

