/** Status glyph. Swaps with a 150 ms blur crossfade on real changes, never on first paint. */
export function BackgroundRunGlyph({ status }: { status: BackgroundRunStatus }) {
  const first = React.useRef(status)
  const changed = React.useRef(false)
  if (status !== first.current) changed.current = true
  let glyph: React.ReactNode
  let tone = "text-(color:--chatcn-fg-subtle)"
  switch (status) {
    case "running":
      glyph = <Spinner className="size-4" />
      tone = "text-(color:--chatcn-blue)"
      break
    case "needs-input":
      glyph = <HandIcon />
      tone = "text-(color:--chatcn-amber)"
      break
    case "done":
      glyph = <CheckIcon />
      tone = "text-(color:--chatcn-green)"
      break
    case "failed":
      glyph = <CircleXIcon />
      tone = "text-(color:--chatcn-red)"
      break
    case "cancelled":
      glyph = <CircleStopIcon />
      break
    default:
      glyph = <CircleDashedIcon />
  }
  return (
    <span
      aria-hidden="true"
      data-slot="background-run-glyph"
      className={cn("grid size-4 shrink-0 place-items-center [&_svg]:size-4", tone)}
    >
      <span
        key={status}
        className={cn(
          "grid place-items-center",
          changed.current && "motion-safe:animate-[chatcn-swap_150ms_var(--chatcn-ease-out)]",
        )}
      >
        {glyph}
      </span>
    </span>
  )
}

/** One line that crossfades with a 4 px rise when its content changes. */
function StepLine({
  stepKey,
  wrap = false,
  className,
  children,
}: {
  stepKey: React.Key
  /** Settled lines (a result, an error, a request) get two lines; a moving step stays on one. */
  wrap?: boolean
  className?: string
  children: React.ReactNode
}) {
  return (
    <span className={cn("grid min-w-0", className)}>
      <span
        key={stepKey}
        className={cn(
          "col-start-1 row-start-1",
          wrap ? "line-clamp-2 text-pretty [overflow-wrap:anywhere]" : "truncate",
          "ease-(--chatcn-ease-out) transition-[opacity,translate] duration-200",
          "starting:translate-y-1 starting:opacity-0 motion-reduce:starting:translate-y-0",
        )}
      >
        {children}
      </span>
    </span>
  )
}

/** Stable key for a node, so the crossfade plays only when the text changes. */
function keyOf(node: React.ReactNode, fallback: string) {
  return typeof node === "string" || typeof node === "number" ? String(node) : fallback
}

