/**
 * One run as a list row for an inbox: unread dot, glyph, title, the latest line and the time.
 * The whole row is the button. Pair with `RunInbox` or your own list.
 */
export function BackgroundRunRow({ run, selected, className, ...props }: BackgroundRunRowProps) {
  const time = useRunTime(run)
  const line = secondaryLine(run)
  return (
    <button
      type="button"
      data-slot="background-run-row"
      data-run-status={run.status}
      data-selected={selected ? "" : undefined}
      aria-current={selected ? "true" : undefined}
      className={cn(
        "group/run-row rounded-(--chatcn-radius-md) relative flex w-full min-w-0 items-start gap-2.5 py-2.5 ps-2 pe-2.5 text-start",
        "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) outline-none select-none",
        "ease-(--chatcn-ease-standard) hover:bg-(color:--chatcn-fill-hover) transition-colors duration-150",
        "focus-visible:outline-(color:--chatcn-accent) focus-visible:outline-2 focus-visible:-outline-offset-2",
        "data-[selected]:bg-(color:--chatcn-fill)",
        "pointer-coarse:min-h-14",
        className,
      )}
      {...props}
    >
      <span aria-hidden="true" className="grid h-5 w-1.5 shrink-0 place-items-center">
        {run.unread ? <UnreadDot /> : null}
      </span>
      <span className="mt-0.5">
        <BackgroundRunGlyph status={run.status} />
      </span>
      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
        <span className="flex min-w-0 items-baseline gap-2">
          <span className={cn("min-w-0 flex-1 truncate", run.unread && "font-medium")}>
            {run.title}
          </span>
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
            {run.status === "needs-input" ? (
              <span className="text-(color:--chatcn-fg) font-medium">Needs input</span>
            ) : run.status === "failed" ? (
              <span className="text-(color:--chatcn-red) font-medium">Failed</span>
            ) : run.status === "queued" ? (
              "Queued"
            ) : (
              time
            )}
          </span>
        </span>
        {line ? (
          <span
            className={cn(
              "text-[0.8125rem]/[1.25rem] min-w-0",
              run.status === "needs-input" ? "text-(color:--chatcn-fg-muted)" : "text-(color:--chatcn-fg-subtle)",
            )}
          >
            <StepLine stepKey={keyOf(line, run.status)}>{line}</StepLine>
          </span>
        ) : null}
        {run.context ? (
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) truncate font-mono">
            {run.context}
          </span>
        ) : null}
      </span>
      <ChevronRightIcon
        aria-hidden="true"
        className={cn(
          "text-(color:--chatcn-fg-subtle) mt-0.5 size-4 shrink-0 opacity-0 transition-opacity duration-150 rtl:-scale-x-100",
          "group-hover/run-row:opacity-100 group-focus-visible/run-row:opacity-100 group-data-[selected]/run-row:opacity-100 pointer-coarse:opacity-100",
        )}
      />
      {run.unread ? <span className="sr-only">, unread</span> : null}
