}

/* -------------------------------------------------------------------------------------------------
 * BackgroundRun (card)
 * -----------------------------------------------------------------------------------------------*/

export interface BackgroundRunProps
  extends Omit<React.ComponentProps<"article">, "title" | "id">,
    Omit<BackgroundRunData, "id"> {
  id?: string
  onOpen?: () => void
  onCancel?: () => void
  onRetry?: () => void
  /** Primary action for `needs-input`. Defaults to `onOpen` labelled Respond. */
  onRespond?: () => void
  /** Replace the default actions. */
  actions?: React.ReactNode
}

function progressOf(run: Pick<BackgroundRunData, "progress" | "steps">) {
  if (run.progress !== undefined) return Math.max(0, Math.min(1, run.progress))
  if (run.steps && run.steps.total > 0) return Math.min(1, run.steps.done / run.steps.total)
  return undefined
}

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

const STATUS_LABEL: Record<BackgroundRunStatus, string> = {
  queued: "Queued",
  running: "Running",
  "needs-input": "Needs input",
  done: "Done",
  failed: "Failed",
  cancelled: "Cancelled",
}

type ButtonVariant = "solid" | "outline" | "ghost" | "subtle"

type ButtonSize = "xs" | "sm" | "md" | "lg" | "icon-xs" | "icon-sm" | "icon-md" | "icon-lg"

interface ButtonProps extends React.ComponentProps<"button"> {
  variant?: ButtonVariant
  size?: ButtonSize
}

const base = cn(
  "chatcn-focus inline-flex shrink-0 items-center justify-center gap-1.5 font-medium whitespace-nowrap select-none",
  "ease-(--chatcn-ease-standard) transition-[background-color,color,box-shadow,scale] duration-150",
  "active:scale-(--chatcn-press-scale) active:duration-100 disabled:pointer-events-none disabled:opacity-50",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0",
)

const variants: Record<ButtonVariant, string> = {
  solid: "bg-(color:--chatcn-primary) text-(color:--chatcn-primary-fg) hover:bg-(color:--chatcn-primary-hover)",
  outline: "bg-(color:--chatcn-card) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-xs) hover:bg-(color:--chatcn-fill-hover)",
  ghost: "text-(color:--chatcn-fg-muted) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg)",
  subtle: "bg-(color:--chatcn-fill) text-(color:--chatcn-fg) hover:bg-(color:--chatcn-fill-hover)",
}

// Heights follow the control scale: 24, 28, 32, 36. Radii stay concentric inside 12 px surfaces.
const sizes: Record<ButtonSize, string> = {
  xs: "h-6 rounded-(--chatcn-radius-sm) px-2 text-[0.75rem]/[1rem] [&_svg]:size-3.5",
  sm: "h-7 rounded-(--chatcn-radius-sm) px-2.5 text-[0.8125rem]/[1.25rem] [&_svg]:size-3.5",
  md: "h-8 rounded-(--chatcn-radius-md) px-3 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  lg: "h-9 rounded-(--chatcn-radius-md) px-3.5 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  "icon-xs": "size-6 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-sm": "size-7 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-md": "size-8 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
  "icon-lg": "size-9 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
}

/** Class names for anything that should look like a button, such as a link. */
function buttonVariants({
  variant = "ghost",
  size = "md",
}: {
  variant?: ButtonVariant
  size?: ButtonSize
} = {}) {
  return cn(base, variants[variant], sizes[size])
}

function Button({
  variant = "ghost",
  size = "md",
  type = "button",
  className,
  ...props
}: ButtonProps) {
  return (
    <button
      type={type}
      data-slot="button"
      data-variant={variant}
      className={cn(buttonVariants({ variant, size }), className)}
      {...props}
    />
  )
}

const iconNode7: IconNode = [
  ["path", {"d":"M5.49 17.46A8.5 8.5 0 1 0 6.54 5.49"}],
  ["path", {"d":"m8.21 8.65-2.94-.26a2 2 0 0 1-1.82-2.16l.26-2.94"}],
]

const RotateCcwIcon: Icon = /* @__PURE__ */ createIcon("rotate-ccw", iconNode7)

/**
 * Card for a detached agent task: what it is, where it runs, the latest step, a 2 px progress
 * line on the bottom edge and Open or Cancel. Queued, running, needs input, done, failed and
 * cancelled each get their own glyph, line and actions.
 */
export function BackgroundRun({
  id,
  title,
  status,
  context,
  step,
  request,
  summary,
  error,
  progress,
  steps,
  queuePosition,
  startedAt,
  durationMs,
  unread,
  onOpen,
  onCancel,
  onRetry,
  onRespond,
  actions,
  className,
  ...props
}: BackgroundRunProps) {
  const run: BackgroundRunData = {
    id: id ?? "",
    title,
    status,
    context,
    step,
    request,
    summary,
    error,
    progress,
    steps,
    queuePosition,
    startedAt,
    durationMs,
  }
  const time = useRunTime(run)
  const value = progressOf(run)
  const line = secondaryLine(run)
  const titleId = React.useId()
  // One running signal per card: the spinner. The bar only shows progress it can measure, so an
  // unknown amount never adds a second, sliding motion beside the spinner.
  const showBar =
    status === "queued" ||
    ((status === "running" || status === "needs-input") && value !== undefined)

  return (
    <article
      aria-labelledby={titleId}
      data-slot="background-run"
      data-run-status={status}
      className={cn(
        "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) relative flex flex-col overflow-hidden",
        "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) forced-colors:outline-1 forced-colors:outline-solid",
        className,
      )}
      {...props}
    >
      <div className="flex flex-col gap-3 p-4 pb-3">
        <div className="flex min-w-0 items-start gap-2.5">
          <span className="mt-0.5">
            <BackgroundRunGlyph status={status} />
          </span>
          <div className="flex min-w-0 flex-1 flex-col gap-0.5">
            <div className="flex min-w-0 items-baseline gap-2">
              <h3 id={titleId} className="flex min-w-0 flex-1 items-center gap-2 font-medium">
                {/* Truncate on a span: headings can inherit text-wrap: balance, which beats nowrap. */}
                <span className="min-w-0 truncate">{title}</span>
                {unread ? (
                  <>
                    <UnreadDot />
                    <span className="sr-only">, unread</span>
                  </>
                ) : null}
              </h3>
              {time ? (
                <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
                  {time}
                </span>
              ) : null}
            </div>
            <div className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex min-w-0 items-center gap-1.5">
              <span
                aria-live="polite"
                className={cn(
                  "shrink-0 font-medium",
                  status === "failed"
                    ? "text-(color:--chatcn-red)"
                    : status === "needs-input"
                      ? "text-(color:--chatcn-fg)"
                      : "text-(color:--chatcn-fg-muted)",
                )}
              >
                {STATUS_LABEL[status]}
              </span>
              {steps && status !== "queued" ? (
                <>
                  <span aria-hidden="true">·</span>
                  <span className="shrink-0 tabular-nums">
                    {Math.min(steps.done, steps.total)} of {steps.total}
                  </span>
                </>
              ) : null}
              {context ? (
                <>
                  <span aria-hidden="true">·</span>
                  <span className="min-w-0 truncate font-mono">{context}</span>
                </>
              ) : null}
            </div>
          </div>
        </div>

        {line ? (
          <div
            data-slot="background-run-line"
            className={cn(
              "text-[0.8125rem]/[1.25rem] flex min-w-0 items-start gap-2 ps-6.5",
              status === "needs-input" ? "text-(color:--chatcn-fg)" : "text-(color:--chatcn-fg-muted)",
            )}
          >
            {status === "needs-input" ? (
              // Sits in the gutter, so the text still lines up with the title.
              <span
                aria-hidden="true"
                className="bg-(color:--chatcn-fg) my-[3px] -ms-2.5 w-0.5 shrink-0 self-stretch rounded-full"
              />
            ) : null}
            <StepLine
              stepKey={keyOf(line, status)}
              wrap={status !== "running" && status !== "queued"}
              className="flex-1"
            >
              {line}
            </StepLine>
          </div>
        ) : null}

        <div className="flex items-center justify-end gap-1.5 ps-6.5 empty:hidden">
          {actions ?? (
            <>
              {isActive(status) || status === "queued"
                ? onCancel && (
                    <Button size="sm" onClick={onCancel}>
                      Cancel
                    </Button>
                  )
                : null}
              {status === "failed" && onRetry ? (
                <Button size="sm" onClick={onRetry}>
                  <RotateCcwIcon />
                  Retry
                </Button>
              ) : null}
              {status === "needs-input" && (onRespond ?? onOpen) ? (
                <Button size="sm" variant="solid" onClick={onRespond ?? onOpen}>
                  Respond
                </Button>
              ) : onOpen ? (
                <Button size="sm" variant="outline" onClick={onOpen}>
                  Open
                </Button>
              ) : null}
            </>
          )}
        </div>
      </div>

      {showBar ? (
        <RunProgress
          value={status === "queued" ? 0 : value}
          label={typeof title === "string" ? `${title} progress` : "Run progress"}
          className="absolute inset-x-0 bottom-0"
        />
      ) : null}
    </article>
  )
}

export default BackgroundRun

